// Expected values below are worked out by hand from SRD 5.2.1, not generated by the engine.
// Each fixture states the math for HP since that's the number most easily got wrong.
import type { Ability, AbilityScores, Character, CharacterFeat, HomebrewPack } from "@/lib/rules";

export type Expected = {
  pb: number; ac: number; hp: number; init: number; passive: number; speed: number; attacks: number;
  attack?: { id: string; toHit: number; damage: string };
  saves?: Partial<Record<Ability, number>>;
  skills?: Record<string, number>;
  spell?: { classId: string; dc: number; attack: number; cantrips: number; prepared: number };
  slots?: number[];
  pact?: { count: number; level: number };
  resources?: Record<string, number>;
  table?: Record<string, unknown>;
  hitDice?: Record<string, number>;
  graze?: number;
  critMin?: number;
};
export type Fixture = { name: string; character: Character; expected: Expected };

const scores = (str: number, dex: number, con: number, int: number, wis: number, cha: number): AbilityScores => ({ str, dex, con, int, wis, cha });
const asi = (abilityIncreases: Partial<AbilityScores>): CharacterFeat => ({ featId: "ability-score-improvement", abilityIncreases });
const feat = (featId: string): CharacterFeat => ({ featId });
const items = (...ids: string[]) => ids.map((itemId) => ({ itemId, equipped: true }));

type Build = Omit<Character, "name" | "classes"> & { classId: string; subclassId: string };
const build = (b: Build, level: number, extra: Partial<Character> = {}): Character => {
  const { classId, subclassId, ...rest } = b;
  return { name: `${classId} ${level}`, classes: [{ classId, level, subclassId: level >= 3 ? subclassId : undefined }], ...rest, ...extra, feats: [...b.feats, ...(extra.feats ?? [])] };
};

